import { GlossaryPage } from "@/components/glossary/glossary-page";
import { glossaryPageCopy } from "@/data/pages/glossary";
import { readDocDocument } from "@/lib/docs/tree";
import { GlossaryUnreadable, type GlossaryDocument, parseGlossary } from "@/lib/glossary";
import type { Metadata } from "next";

/**
 * `/glossary` — the product glossary, published from the document that already is one (#1289,
 * register row WEB-07).
 *
 * **The register is `docs/glossary.md`, and this page is a second rendering of it.** That file is
 * generated by `scripts/gen-glossary.mjs` from the JSDoc comments and glossary lines in
 * `content/`, and `pnpm glossary:check` fails the gate in every lane while it is stale. So the
 * page reads it — `readDocDocument`, the one reader that resolves a path inside `docs/` — and
 * parses it with `lib/glossary.ts`. Nothing is copied into a component or a fixture: a definition
 * added to the site's own markup would be a second register, and the schema comment would stop
 * being the only place a definition is written.
 *
 * **Request-time, deliberately.** `force-dynamic`, like `/admin/docs`: a comment rewritten in the
 * schema, regenerated into the document and deployed is live on the next request, and `pnpm build`
 * needs no part of it. The marketing group's layout already renders per request in a deployment
 * (it reads the session cookie for the account slot), so this costs no prerender that the group
 * had. Read once per render: the parse is one pass over a 63-line file.
 *
 * **Why a missing or malformed document is `null` rather than a throw.** A public reader gets the
 * fixture's `document-unavailable` sentence, which names the file and the command that writes it —
 * an actionable statement instead of a 500. The reason the parse refused is deliberately not
 * printed to that reader; the diagnosis belongs to `pnpm glossary:check` and
 * `tests/glossary.test.ts`, which are where a drift in the generator shows up first.
 */
export const metadata: Metadata = {
  /** One string, `<h1>` and `<title>` alike: the fixture's heading. */
  title: glossaryPageCopy.heading,
  description: glossaryPageCopy.subtitle,
};

export const dynamic = "force-dynamic";

/** The document's path inside `docs/`. One constant: the page, the fixture's sentence and the test
 * all name this file. */
export const GLOSSARY_DOCUMENT_PATH = "glossary.md";

/** The document, parsed — or `null` when it is absent or no longer parses (see the docstring). */
function readGlossary(): GlossaryDocument | null {
  const markdown = readDocDocument(GLOSSARY_DOCUMENT_PATH);
  if (markdown === null) return null;
  try {
    return parseGlossary(markdown);
  } catch (error) {
    if (error instanceof GlossaryUnreadable) return null;
    throw error;
  }
}

export default function GlossaryRoute() {
  return <GlossaryPage copy={glossaryPageCopy} document={readGlossary()} />;
}
